thinker.handleSteps:
function* () {
    const { agentState } = yield "STEP", lastAssistantMessage = [...agentState.messageHistory].reverse().find((m) => m.role === "assistant");
    if (!lastAssistantMessage) {
      yield {
        toolName: "set_output",
        input: { message: "Error: No assistant message found in conversation history" }
      };
      return;
    }
    const content = lastAssistantMessage.content;
    let textContent = "";
    if (typeof content === "string")
      textContent = content;
    else if (Array.isArray(content))
      textContent = content.filter((part) => part.type === "text").map((part) => part.text).join("");
    yield {
      toolName: "set_output",
      input: { message: textContent.replace(/<think>[\s\S]*?<\/think>/g, "").trim() },
      includeToolCall: !1
    };
  }

thinker-best-of-n.handleSteps:
function* handleStepsDefault({
  agentState,
  prompt,
  params
}) {
  const n = Math.min(10, Math.max(1, params?.n ?? 3)), { nResponses = [] } = yield {
    type: "GENERATE_N",
    n
  }, thoughts = nResponses.map((content, index) => ({
    id: "ABCDEFGHIJKLMNOPQRSTUVWXYZ"[index],
    content: content.replace(/<think>[\s\S]*?<\/think>/g, "").trim()
  })), { toolResult: selectorResult } = yield {
    toolName: "spawn_agents",
    input: {
      agents: [
        {
          agent_type: "thinker-selector",
          params: { thoughts }
        }
      ]
    },
    includeToolCall: !1
  }, selectorOutput = extractSpawnResults(selectorResult)[0];
  if ("errorMessage" in selectorOutput) {
    yield {
      type: "STEP_TEXT",
      text: selectorOutput.errorMessage
    };
    return;
  }
  const { thoughtId } = selectorOutput, chosenThought = thoughts.find((thought) => thought.id === thoughtId);
  if (!chosenThought) {
    yield {
      type: "STEP_TEXT",
      text: "Failed to find chosen thinking output."
    };
    return;
  }
  yield {
    type: "STEP_TEXT",
    text: chosenThought.content
  };
  function extractSpawnResults(results) {
    if (!results)
      return [];
    return results.filter((result) => result.type === "json").map((result) => result.value).flat().map((result) => result.value.value ?? {
      errorMessage: result.value.errorMessage ?? "Error extracting spawn results"
    });
  }
}

