      logger.error("No command provided in params.command");
      yield {
        toolName: "set_output",
        input: {
          overallStatus: "failure",
          summary: "No command provided. Pass params.command with the CLI command to start.",
          sessionName: "",
          scriptIssues: [],
          captures: []
