    logger.info("Cloning " + repoUrl + " into " + cloneDir);
    const { toolResult } = yield {
      toolName: "run_terminal_command",
      input: {
        command: "git clone --depth 1 '" + repoUrl + "' '" + cloneDir + "'",
        timeout_seconds: 180
      }
    }, result = toolResult?.[0];
    if (result && result.type === "json") {
      const value = result.value;
      if ((typeof value?.exitCode === "number" ? value.exitCode : void 0) !== 0) {
        const stderr = typeof value?.stderr === "string" ? value.stderr : "Unknown error";
        logger.error("Clone failed: " + stderr);
        yield {
          toolName: "set_output",
          input: {
            message: "Failed to clone repository: " + stderr
          }
