function* handleStepsMultiPrompt({
  params,
  agentState
}) {
  const prompts = params?.prompts ?? [];
  if (prompts.length === 0) {
    yield {
      toolName: "set_output",
      input: {
        error: "No prompts provided. Please pass an array of review focus prompts."
      }
    };
    return;
  }
  const { messageHistory } = agentState;
  while (messageHistory.length > 0 && messageHistory[messageHistory.length - 1].role === "user")
    messageHistory.pop();
  yield {
    toolName: "set_messages",
    input: {
      messages: messageHistory
    },
    includeToolCall: !1
  };
  const reviewerAgents = prompts.map((prompt) => ({
    agent_type: "code-reviewer-opus",
    prompt: `Review the above code changes with the following focus: ${prompt}`
  })), { toolResult: reviewerResults } = yield {
    toolName: "spawn_agents",
    input: {
      agents: reviewerAgents
    },
    includeToolCall: !1
  }, spawnedReviews = extractSpawnResults(reviewerResults), reviewTexts = [];
  for (const review of spawnedReviews)
    if ("errorMessage" in review)
      reviewTexts.push(`Error: ${review.errorMessage}`);
    else
      for (const message of review)
        for (const block of message.content)
          if (block.type === "text" && block.text)
            reviewTexts.push(block.text);
  yield {
    toolName: "set_output",
    input: {
      reviews: reviewTexts
    },
    includeToolCall: !1
  };
  function extractSpawnResults(results) {
    if (!results || results.length === 0)
      return [];
    const jsonResult = results.find((r) => r.type === "json");
    if (!jsonResult?.value)
      return [];
    const spawnedResults = Array.isArray(jsonResult.value) ? jsonResult.value : [jsonResult.value], extracted = [];
    for (const result of spawnedResults) {
      const innerValue = result?.value;
      if (innerValue && typeof innerValue === "object" && "value" in innerValue)
        extracted.push(innerValue.value);
      else if (innerValue && typeof innerValue === "object" && "errorMessage" in innerValue)
        extracted.push({ errorMessage: String(innerValue.errorMessage) });
      else if (innerValue != null)
        extracted.push(innerValue);
    }
    return extracted;
  }
}

