          toolName: "set_output",
          input: {
            message: "Failed to clone repository: " + stderr
          }
        };
        return;
      }
    }
    logger.info("Clone complete. Exploring repo...");
    yield {
      toolName: "add_message",
      input: {
        role: "user",
