    if [[ "$AUTO_ENTER" == true ]]; then
      sleep 0.05
      tmux send-keys -t "$SESSION" Enter
      sleep 0.5
    fi
    if [[ "$WAIT_IDLE" -gt 0 ]]; then
      LAST_OUTPUT=""
      STABLE_START=$(date +%s)
      MAX_END=$(( $(date +%s) + 120 ))
