      };
    return {
      id: letters[index],
      strategy: prompts[index] ?? "unknown",
      content: result.unifiedDiffs || "No changes proposed",
      toolCalls: result.toolCalls ?? []
    };
  }), { toolResult: selectorResult } = yield {
    toolName: "spawn_agents",
    input: {
      agents: [
        {
          agent_type: "best-of-n-selector2",
